    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = DateTime.UtcNow });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking change fixes ---
class CosmosDbContext : DbContext
{
    public DbSet<Vehicle> Vehicles => Set<Vehicle>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=fake==",
            "VehiclesDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1: EF Core 9 renamed the discriminator property
        // from "Discriminator" to "$type". For existing documents that already
        // use "Discriminator", explicitly configure the old property name.
        modelBuilder.Entity<Vehicle>()
            .HasDiscriminator<string>("Discriminator")
            .HasValue<Car>("Car")
            .HasValue<Truck>("Truck");

        modelBuilder.Entity<Vehicle>().ToContainer("Vehicles");
    }
}

abstract class Vehicle { public string Id { get; set; } = null!; public string Make { get; set; } = null!; }
class Car : Vehicle { public int Seats { get; set; } }
class Truck : Vehicle { public double PayloadTons { get; set; } }

// --- Cosmos DB query service demonstrating sync-to-async fix ---
class VehicleService
{
    // BREAKING CHANGE 2: EF Core 9 Cosmos provider no longer supports
    // synchronous I/O (e.g., ToList(), First()). All queries must be async.
    public async Task<List<Vehicle>> GetAllVehiclesAsync(CosmosDbContext db)
    {
        return await db.Vehicles.ToListAsync();
    }

    public async Task<Vehicle?> GetVehicleAsync(CosmosDbContext db, string id)
    {
        return await db.Vehicles.FirstOrDefaultAsync(v => v.Id == id);
    }
}

